import React, { useState } from 'react';
import './styles.css';

const COLUMNS = [
  { key: 'todo', label: '待办', testId: 'column-todo' },
  { key: 'progress', label: '进行中', testId: 'column-progress' },
  { key: 'done', label: '已完成', testId: 'column-done' },
];

let nextId = 1;

export default function App() {
  const [input, setInput] = useState('');
  const [tasks, setTasks] = useState([]);

  function handleAdd() {
    const title = input.trim();
    if (!title) return;
    setTasks((prev) => [...prev, { id: nextId++, title, status: 'todo' }]);
    setInput('');
  }

  return (
    <main className="board">
      <h1>本地任务看板</h1>
      <div className="add-row">
        <input
          data-testid="title-input"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="输入任务标题"
        />
        <button data-testid="add-button" onClick={handleAdd}>添加</button>
      </div>
      <div className="columns">
        {COLUMNS.map((col) => (
          <section key={col.key} className="column" data-testid={col.testId}>
            <h2>{col.label}</h2>
            <ul className="task-list">
              {tasks
                .filter((t) => t.status === col.key)
                .map((t) => (
                  <li key={t.id} className="task" data-testid="task-item">
                    <span className="task-title">{t.title}</span>
                  </li>
                ))}
            </ul>
          </section>
        ))}
      </div>
    </main>
  );
}

