import React, { useState } from 'react';
import './styles.css';

const COLUMNS = [
  { key: 'todo', label: '待办', testId: 'column-todo' },
  { key: 'progress', label: '进行中', testId: 'column-progress' },
  { key: 'done', label: '已完成', testId: 'column-done' },
];

const ORDER = COLUMNS.map((c) => c.key);

let nextId = 1;

export default function App() {
  const [input, setInput] = useState('');
  const [tasks, setTasks] = useState([]);

  function handleAdd() {
    const title = input.trim();
    if (!title) return;
    setTasks((prev) => [...prev, { id: nextId++, title, status: 'todo' }]);
    setInput('');
  }

  function moveTask(id, delta) {
    setTasks((prev) =>
      prev.map((t) => {
        if (t.id !== id) return t;
        const idx = ORDER.indexOf(t.status);
        const nextIdx = idx + delta;
        if (nextIdx < 0 || nextIdx >= ORDER.length) return t;
        return { ...t, status: ORDER[nextIdx] };
      })
    );
  }

  return (
    <main className="board">
      <h1>本地任务看板</h1>
      <div className="add-row">
        <input
          data-testid="title-input"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="输入任务标题"
        />
        <button data-testid="add-button" onClick={handleAdd}>添加</button>
      </div>
      <div className="columns">
        {COLUMNS.map((col) => (
          <section key={col.key} className="column" data-testid={col.testId}>
            <h2>{col.label}</h2>
            <ul className="task-list">
              {tasks
                .filter((t) => t.status === col.key)
                .map((t) => {
                  const idx = ORDER.indexOf(t.status);
                  const canBack = idx > 0;
                  const canForward = idx < ORDER.length - 1;
                  return (
                    <li key={t.id} className="task" data-testid="task-item">
                      <span className="task-title" data-testid="task-title">{t.title}</span>
                      <div className="task-actions">
                        {canBack && (
                          <button data-testid="move-back" onClick={() => moveTask(t.id, -1)}>
                            后退
                          </button>
                        )}
                        {canForward && (
                          <button data-testid="move-forward" onClick={() => moveTask(t.id, 1)}>
                            前进
                          </button>
                        )}
                      </div>
                    </li>
                  );
                })}
            </ul>
          </section>
        ))}
      </div>
    </main>
  );
}

